fn solve(input: Vec<char>) -> Vec<char> {
    // Helper to map a digit character to its "good count".
    fn good_count(d: char) -> u32 {
        match d {
            '0' => 2,
            '1' => 7,
            '2' => 2,
            '3' => 3,
            '4' => 3,
            '5' => 4,
            '6' => 2,
            '7' => 5,
            '8' => 1,
            '9' => 2,
            _ => unreachable!("Input guaranteed to be a digit"),
        }
    }

    // Take the first two characters.
    let d1 = input[0];
    let d2 = input[1];

    // Compute their good counts and the product.
    let count1 = good_count(d1);
    let count2 = good_count(d2);
    let product = count1 * count2;

    // Convert the product to decimal digits, collect into a Vec<char>,
    // then append a newline.
    let mut result: Vec<char> = product.to_string().chars().collect();
    result.push('\n');
    result
}

